'use strict';
function libraryRender(where,settings){const p=PocketFX.normalized(settings),isLibrary=p.type.startsWith('lib:'),container=$(where==='common'?'#libraryCommon':'#libraryPad');PocketLibrary.state[where]=p;container.hidden=!isLibrary;for(const id of where==='common'?['classicAmount','classicCharacter']:['padFxAmount','padFxCharacter'])$('#'+id).closest?.('.control')?.toggleAttribute('hidden',isLibrary);container.replaceChildren();if(!isLibrary)return;const fields=PocketLibrary.schemas[p.type.slice(4)][1];for(const f of fields){if(f.key==='mix')continue;const label=document.createElement('label');label.className='control';const caption=document.createElement('span');caption.textContent=f.label+(f.unit?' · '+f.unit:'');label.append(caption);const input=document.createElement(f.values?'select':'input');input.className='key';input.setAttribute('aria-label',f.label+' '+where);if(f.values){for(const v of f.values){const o=document.createElement('option');o.value=v;o.textContent=v;input.append(o)}}else{input.type='number';input.min=f.min;input.max=f.max;input.step=f.max-f.min<=30?.01:.1}input.value=p.params[f.key];input.addEventListener('pointerdown',remember);input.onchange=async()=>{remember();const value=f.values?input.value:+input.value;const current=where==='common'?classicSettings():PocketFX.normalized(pads[selected].padFX);PocketLibrary.state[where]={...current,params:{...current.params,[f.key]:value}};if(where==='common'){await audio();await syncEffects()}else{pads[selected].padFX=PocketFX.normalized(PocketLibrary.state[where]);individualContexts.get(ctx)?.get(selected)?.graph.set(pads[selected].padFX)}changed()};label.append(input);container.append(label)}}
libraryRender('common',classicSettings());renderExtra();
